const grid=document.querySelector('#fontGrid'),search=document.querySelector('#search'),previewDisplay=document.querySelector('#previewDisplay'),previewEnglish=document.querySelector('#previewEnglish'),customText=document.querySelector('#customText'),state=document.querySelector('#loadState'),resultCount=document.querySelector('#resultCount');const labels={song:'宋体',hei:'黑体',hand:'手绘体',display:'艺术体',楷体:'楷体','手绘体':'手绘体','艺术体':'艺术体'};const samples={poem:['春风得意\n马蹄疾','A quiet type specimen\nfor every kind of story.'],phrase:['见字如面','Every letter has a feeling.'],mix:['山有木兮木有枝','A quiet type specimen'],custom:['输入你的文字','Your words, your type.']};let fonts=[],filter='all',limit=18,activeFont=null,sort='name';
const normalize=(x,i)=>({name:x.name||x.familyName||`未命名字体 ${i+1}`,en:x.familyName||x.fullName||'Open Font',type:x.type||'艺术体',license:x.license||'授权以作者说明为准',size:x.size||'—',glyphs:x.numGlyphs||0,path:x.path||''});
function cdnUrl(path){return `https://cdn.jsdelivr.net/gh/jaywcjlove/free-font@main/${path.split('/').map(encodeURIComponent).join('/')}`}
function loadFont(font){if(!font.path)return '';const family=`Specimen-${fonts.indexOf(font)}`;if(!document.getElementById(family)){const style=document.createElement('style');style.id=family;style.textContent=`@font-face{font-family:'${family}';src:url('${cdnUrl(font.path)}') format('truetype');font-display:swap}`;document.head.append(style)}return family}
function visible(){const q=search.value.trim().toLowerCase();let list=fonts.filter(f=>(filter==='all'||f.type===filter)&&(!q||`${f.name} ${f.en}`.toLowerCase().includes(q)));return list.sort((a,b)=>sort==='glyphs'?b.glyphs-a.glyphs:a.name.localeCompare(b.name,'zh')).slice(0,limit)}
function render(){const all=visible(),family=activeFont&&loadFont(activeFont);grid.innerHTML=all.map(f=>`<article class="font-card${f===activeFont?' selected':''}" data-index="${fonts.indexOf(f)}" tabindex="0"><div class="card-top"><span class="tag">${labels[f.type]||f.type||'字体'}</span><button class="favorite" aria-label="收藏 ${f.name}">♡</button></div><div class="specimen" style="font-family:${f===activeFont?`'${family}'`:'var(--serif)'}">${previewDisplay.textContent.replace(/\n/g,' ')}</div><div class="font-name">${f.name}</div><div class="font-meta">${f.en}　·　${f.size}　·　${f.glyphs.toLocaleString()} glyphs</div><div class="card-foot"><span>${f.license}</span><span>${f===activeFont?'CDN 已加载':'点击试读'}</span></div></article>`).join('');resultCount.textContent=`${all.length} / ${fonts.length}`;document.querySelector('#empty').style.display=all.length?'none':'block';document.querySelector('#loadMore').style.display=all.length<fonts.filter(f=>filter==='all'||f.type===filter).length?'block':'none';document.querySelectorAll('.font-card').forEach(card=>{card.onclick=e=>{if(e.target.closest('.favorite'))return;activeFont=fonts[Number(card.dataset.index)];state.textContent='LOADING CDN';const loaded=loadFont(activeFont);document.querySelector('#selectedName').textContent=activeFont.name;document.querySelector('#selectedMeta').textContent=`${activeFont.en} · ${activeFont.size} · ${activeFont.glyphs.toLocaleString()} glyphs`;previewDisplay.style.fontFamily=`'${loaded}'`;state.textContent='CDN LOADED';render()};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}}});document.querySelectorAll('.favorite').forEach(b=>b.onclick=()=>{b.classList.toggle('saved');b.textContent=b.classList.contains('saved')?'♥':'♡'})}
function setSample(kind){const [cn,en]=samples[kind];previewDisplay.textContent=cn;previewEnglish.textContent=en;customText.style.display=kind==='custom'?'block':'none';if(kind==='custom')customText.focus();render()}
async function init(){try{const r=await fetch('data.json');fonts=(await r.json()).map(normalize)}catch{fonts=[['霞鹜文楷','LXGW WenKai','宋体','开源 / SIL OFL'],['思源黑体','Source Han Sans','黑体','开源 / OFL'],['得意黑','Smiley Sans','艺术体','开源 / OFL']].map(([name,en,type,license])=>({name,en,type,license,size:'—',glyphs:0,path:''}))}resultCount.textContent=`${fonts.length} 款`;render()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelector('.tab.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;limit=18;render()});document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>{document.querySelector('.sample.active').classList.remove('active');b.classList.add('active');setSample(b.dataset.sample)});customText.oninput=()=>{if(document.querySelector('.sample.active').dataset.sample==='custom'){previewDisplay.textContent=customText.value||'输入你的文字';render()}};document.querySelector('#clearSelected').onclick=()=>{activeFont=null;previewDisplay.style.fontFamily='';document.querySelector('#selectedName').textContent='未选择字体';document.querySelector('#selectedMeta').textContent='点击右侧字体卡片开始试读';state.textContent='READY';render()};document.querySelector('#sort').onchange=e=>{sort=e.target.value;render()};search.oninput=()=>{limit=18;render()};document.querySelector('#loadMore').onclick=()=>{limit+=18;render()};document.querySelectorAll('.view').forEach(b=>b.onclick=()=>{document.querySelector('.view.active').classList.remove('active');b.classList.add('active');grid.style.gridTemplateColumns=b.dataset.view==='list'?'1fr':''});document.querySelector('#themeToggle').onclick=()=>document.body.classList.toggle('dark');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();search.focus()}});setSample('poem');init();
